export default {

	defaultTab: 'Sign In',

	setDefaultTab: (newTab) => {
		this.defaultTab = newTab;
	},

	generatePasswordHash: (password) => {
		return dcodeIO.bcrypt.hashSync(password, 10);
	},

	verifyPassword: (password, hash) => {
		return dcodeIO.bcrypt.compareSync(password, hash);
	},

	signIn: async () => {
		const password = inp_password.text;
		const result = await findUserByEmail.run(); 
		const user = result[0];
		if (user && this.verifyPassword(password, user.password)) {
			await storeValue('currentUser', user.email);
			showAlert('Login Success', 'success');
			navigateTo('MainApp');
		} else {
			showAlert('Invalid email or password', 'error');
		}
	},

	register: async () => {
		const password = inp_registerPassword.text;
		const passwordHash = this.generatePasswordHash(password);

		try {
			await createUser.run({ passwordHash: passwordHash });
			showAlert('Registration Success', 'success');
			this.setDefaultTab('Sign In')
		} catch {
			showAlert('Error creating user. Email might exist.', 'error');
		}
	},
}

